import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"kernel","description":"","frontmatter":{},"headers":[],"relativePath":"kernel/index.md","filePath":"vendored/kernel/index.md"}`),a={name:`kernel/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="kernel" tabindex="-1">kernel <a class="header-anchor" href="#kernel" aria-label="Permalink to “kernel”">​</a></h1><p>The arrow-calculus substrate: language schema, tagged values, extension ABI, floor libs.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to “What it is”">​</a></h2><p>The kernel is the platform&#39;s smallest layer (ADR-0040): the <code>Language</code> data schema and staged <code>lex</code>/<code>parse</code>/<code>eval</code> dispatch signatures (ADR-0044, language as data), the tagged <code>Value</code> representation the engines share, the dynamic extension ABI (<code>hnl</code> extensions, ADR-0149), and the <code>handl-lib-*</code> floor packages.</p><p>What is <em>not</em> kernel: engines, emitters, kits, plugins and hosts. They live in the <code>engine-*</code>, <code>kit-*</code> and <code>host</code> repos and depend on the kernel, never the reverse.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><ul><li><code>crates/handl-language</code> — the <code>Language</code> schema + staged lex/parse/eval dispatch signatures</li><li><code>crates/handl-value</code> — the tagged <code>Value</code> representation shared by engines</li><li><code>crates/handl-ext</code> — the shared ABI for dynamic <code>hnl</code> extensions (ADR-0149)</li><li><code>crates/defining-handl</code> — self-hosting infrastructure (ADR-0044 phase 8)</li><li><code>crates/{bytes,cmp,combinators,error,mood,obj,ops,prim,prim-handl,type}</code> — the <code>handl-lib-*</code> substrate packages</li></ul><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to “Start here”">​</a></h2><ul><li><strong>Reference</strong> — <a href="/docs/kernel/reference/">public API</a></li><li><strong>How-to</strong> — <a href="/docs/kernel/how-to/">task recipes</a></li><li><strong>Explanation</strong> — <a href="/docs/kernel/explanation/">design and rationale</a></li></ul><p>No tutorials: this repo is a building block used from Rust. End-to-end walkthroughs live with the product that composes it — see the <a href="/docs/handl/">Handl platform</a>.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};